    // ─────────── فصل ۱: کوری سفید ───────────
    private fun chapter1() = StoryChapter(
        number = 1, title = "The White Blindness", titlePersian = "کوری سفید",
        paragraphs = listOf(
            StoryParagraph("The driver sat motionless at the intersection, his hands still gripping the steering wheel, while the traffic light before him shifted from green to amber to red and back again, and he did not move, because he could no longer perceive any of it.", "راننده بی‌حرکت پشت چهارراه نشسته بود، دست‌هایش هنوز فرمان را چنگ زده بودند، در حالی که چراغ راهنمایی پیش رویش از سبز به زرد به سرخ و دوباره به سبز تغییر می‌کرد و او تکان نمی‌خورد، چون دیگر نمی‌توانست هیچ‌کدام را درک کند."),
            StoryParagraph("What had descended upon him was not the familiar darkness that the blind have always described, nor the gradual dimming that accompanies age or illness, but something far more disorienting: an absolute, luminous whiteness, as though he had been plunged into a vat of milk.", "آنچه بر او نازل شده بود نه تاریکی آشنایی بود که نابینایان همیشه توصیف کرده‌اند، و نه کم‌نوری تدریجی‌ای که با پیری یا بیماری می‌آید، بلکه چیزی بسیار گیج‌کننده‌تر: سفیدی مطلق و درخشان، گویی در تشتی از شیر فرو برده شده بود."),
            StoryParagraph("It was a whiteness without depth, without shadow, without any of the gradations that give the visible world its texture; it was as though the universe had been erased and replaced by a single, uniform blank.", "سفیدی‌ای بود بدون عمق، بدون سایه، بدون هیچ‌کدام از درجات که به دنیای مرئی بافتش را می‌دهد؛ گویی کائنات پاک شده بود و جایگزینش شده بود با یک سفید یکنواخت و یکسان."),
            StoryParagraph("A passing pedestrian, noticing the strange stillness of the car and the unnatural rigidity of its occupant, approached the window and asked if the driver required assistance.", "رهگذری که سکون عجیب ماشین و سختی غیرطبیعی سرنشینش را متوجه شده بود، به پنجره نزدیک شد و پرسید آیا راننده به کمک نیاز دارد."),
            StoryParagraph("'I am blind,' the man whispered, and the words carried a weight of disbelief that made them sound less like a statement of fact and more like a question addressed to the universe itself.", "مرد زمزمه کرد: «کور شده‌ام،» و کلمات وزنی از ناباوری داشتند که آن‌ها را کمتر شبیه بیان واقعیت و بیشتر شبیه پرسشی خطاب به خود هستی می‌کرد."),
            StoryParagraph("'But you are looking at me,' the stranger protested. 'Your eyes are open. They seem perfectly normal.'", "غریبه اعتراض کرد: «اما شما به من نگاه می‌کنید. چشمانتان باز است. کاملاً عادی به نظر می‌رسند.»"),
            StoryParagraph("'Nevertheless,' the man said, 'I see nothing but white, and I cannot tell where I am or what is before me, and I am utterly, completely, irretrievably blind.'", "مرد گفت: «با این حال، جز سفیدی چیزی نمی‌بینم و نمی‌توانم بگویم کجا هستم یا پیش رویم چیست و کاملاً، مطلقاً، به‌طور جبران‌ناپذیری کور شده‌ام.»"),
            StoryParagraph("The stranger, a man of instinctive kindness, guided him to the passenger seat and drove him to his apartment, an act of decency that would, within days, cost him his own sight.", "غریبه که مردی با مهربانی غریزی بود، او را به صندلی سرنشین راهنمایی کرد و به آپارتمانش راند، عملی نیک‌خواهانه که در عرض چند روز بینایی خودش را برایش هزینه می‌کرد."),
            StoryParagraph("He did not know, as he helped the blind man up the stairs, that he was already infected; he did not know that the very act of kindness that defined his humanity would be the instrument of his own destruction.", "نمی‌دانست، همان‌طور که به مرد کور کمک می‌کرد از پله‌ها بالا برود، که او هم مبتلا شده بود؛ نمی‌دانست همان عمل مهربانی که انسانیتش را تعریف می‌کرد ابزار نابودی خودش می‌شد."),
            StoryParagraph("By evening, the driver's wife had taken him to an ophthalmologist, who examined his eyes with mounting bewilderment, finding no anatomical cause for the affliction.", "تا عصر، همسر راننده او را به چشم‌پزشکی برده بود که با حیرت فزاینده چشمانش را معاینه کرد و هیچ علت آناتومیکی برای این عارضه نیافت."),
            StoryParagraph("'There is nothing wrong with your eyes,' the doctor said. 'The pupils respond correctly. The retina appears healthy. The optic nerve shows no sign of damage.'", "دکتر گفت: «چیزی در چشمان شما اشتباه نیست. مردمک‌ها درست پاسخ می‌دهند. شبکیه سالم به نظر می‌رسد. عصب بینایی نشانه‌ای از آسیب نشان نمی‌دهد.»"),
            StoryParagraph("'But I cannot see,' the man insisted. 'I see only white, an ocean of white, a whiteness that swallows everything.'", "مرد اصرار کرد: «اما نمی‌بینم. فقط سفیدی می‌بینم، اقیانوسی از سفیدی، سفیدی‌ای که همه چیز را می‌بلعد.»"),
            StoryParagraph("The doctor, unable to formulate a diagnosis, gave the condition a provisional name — the white evil, he called it — and sent the man home with instructions to return if the symptoms changed.", "دکتر که نمی‌توانست تشخیصی فرموله کند، نامی موقت به این وضعیت داد — شر سفید، نامیدش — و مرد را با دستور بازگشت در صورت تغییر علائم به خانه فرستاد."),
            StoryParagraph("Within twenty-four hours, the stranger who had driven him home reported the same symptoms, and by the end of the week, the ophthalmologist himself had joined the growing ranks of the blind.", "در عرض بیست و چهار ساعت، غریبه‌ای که او را به خانه رسانده بود همان علائم را گزارش داد و تا پایان هفته، خود چشم‌پزشک هم به صفوف رو به رشد کورها پیوسته بود."),
            StoryParagraph("The disease, if it could be called a disease, spread with terrifying swiftness, leaping from person to person along lines of contact and proximity.", "بیماری، اگر می‌شد نامش را بیماری گذاشت، با سرعتی هولناک پخش می‌شد و از شخصی به شخصی در امتداد خطوط تماس و مجاورت می‌پرید."),
            StoryParagraph("A thief who had robbed a blind man in an alley was struck the next morning; a prostitute who had serviced a blind client lost her sight before dawn; a beggar who had touched a blind man's hand woke to a world of whiteness.", "دزدی که در کوچه‌ای مرد کوری را غارت کرده بود صبح روز بعد مبتلا شد؛ روسپی‌ای که به مشتری کوری خدمت کرده بود پیش از سپیده بینایی‌اش را از دست داد؛ گدایی که دست مرد کوری را لمس کرده بود به دنیایی از سفیدی بیدار شد."),
            StoryParagraph("The government, in a panic, ordered the afflicted to be quarantined in the abandoned mental hospital on the outskirts of the city.", "دولت از سر وحشت دستور داد مبتلایان در بیمارستان روانی متروکه حاشیه شهر قرنطینه شوند."),
            StoryParagraph("The quarantine was not a humanitarian measure; it was an act of desperation, an attempt to contain a threat that no one understood by isolating those who had been touched by it.", "قرنطینه اقدامی انسانی نبود؛ عملی از درماندگی بود، تلاشی برای مهار تهدیدی که هیچ‌کس نمی‌فهمید با جدا کردن کسانی که لمسش کرده بود."),
            StoryParagraph("Soldiers in protective gear dragged the blind from their homes, from their workplaces, from the hospitals where they had gone seeking help, and herded them into buses that drove them to the asylum.", "سربازان با تجهیزات محافظتی کورها را از خانه‌هایشان، از محل کارشان، از بیمارستان‌هایی که برای کمک رفته بودند بیرون کشیدند و به اتوبوس‌هایی راندند که آن‌ها را به تیمارستان برد."),
            StoryParagraph("The buses smelled of fear and urine and the peculiar, sweet smell of unwashed bodies; the blind sat in silence, their useless eyes staring at nothing, their minds grappling with the enormity of what had happened to them.", "اتوبوس‌ها بوی ترس و ادرار و بوی عجیب و شیرین بدن‌های نشسته را داشتند؛ کورها در سکوت نشسته بودند، چشمان بی‌فایده‌شان به هیچ نگاه می‌کردند، ذهن‌هایشان با عظمت آنچه بر آن‌ها نازل شده بود دست‌وپنجه نرم می‌کردند."),
            StoryParagraph("No one understood the mechanism of transmission; no one knew whether the blindness was permanent; no one could predict who would be next.", "هیچ‌کس مکانیسم انتقال را نمی‌فهمید؛ هیچ‌کس نمی‌دانست آیا کوری دائمی است؛ هیچ‌کس نمی‌توانست پیش‌بینی کند نفر بعدی کیست."),
            StoryParagraph("The blindness did not discriminate by age or class or morality; it struck the young and the old, the rich and the poor, the saint and the sinner, with the same indifferent violence.", "کوری با سن یا طبقه یا اخلاق تبعیض قائل نمی‌شد؛ جوان و پیر، ثروتمند و فقیر، قدیس و گناهکار را با همان خشونت بی‌تفاوت مبتلا می‌کرد."),
            StoryParagraph("And so, with the same silent inevitability with which plague has always descended upon humanity, the white blindness began its slow, terrible conquest of the world.", "و اینگونه، با همان اجتناب‌ناپذیری خاموشی که طاعون همیشه بر بشریت نازل شده است، کوری سفید شروع به فتح آهسته و هولناک دنیا کرد."),
            StoryParagraph("The first cases appeared in the city on a Monday; by Wednesday, the hospitals were overwhelmed; by Friday, the government had declared a state of emergency.", "نخستین موارد روز دوشنبه در شهر ظاهر شدند؛ تا چهارشنبه، بیمارستان‌ها overwhelmed شده بودند؛ تا جمعه، دولت وضعیت اضطراری اعلام کرده بود."),
            StoryParagraph("The blind stumbled through the streets, calling out for help that rarely came, and the sighted, terrified of contagion, retreated behind locked doors and shuttered windows.", "کورها در خیابان‌ها تلپ می‌خوردند و فریاد کمک می‌زدند که به‌ندرت می‌آمد و بینایان که از سرایت وحشت داشتند، پشت درهای قفل و پنجره‌های بسته عقب‌نشینی می‌کردند."),
            StoryParagraph("The city, which had once been a bustling metropolis, became a landscape of nightmare: cars abandoned in the middle of roads, fires burning unchecked in buildings no one could reach, the cries of the lost echoing through empty squares.", "شهری که زمانی کلان‌شهری پرجنب‌وجوش بود، به منظره‌ای از کابوس تبدیل شد: ماشین‌های رهاشده در میانه جاده‌ها، آتش‌هایی که در ساختمان‌هایی که هیچ‌کس نمی‌توانست به آن‌ها برسد بی‌مهار می‌سوختند، فریادهای گمشدگان در میدان‌های خالی می‌پیچیدند."),
            StoryParagraph("The government, unable to contain the crisis, began to collapse under its own weight; departments ceased to function, services broke down, and the thin veneer of civilization that had held society together began to crack.", "دولت که نمی‌توانست بحران را مهار کند، زیر وزن خودش شروع به فروپاشی کرد؛ بخش‌ها از کار افتادند، خدمات قطع شدند و پوسته نازک تمدنی که جامعه را کنار هم نگه داشته بود شروع به ترک خوردن کرد."),
            StoryParagraph("It was in this context of chaos that the first cases were brought to the quarantine — the driver, the stranger who had helped him, the ophthalmologist, and a growing number of others who had been unfortunate enough to come into contact with them.", "در همین زمینه از آشفتگی بود که نخستین موارد به قرنطینه آورده شدند — راننده، غریبه‌ای که کمکش کرده بود، چشم‌پزشک و تعداد رو به رشدی از دیگرانی که به‌قدر کافی بدشانس بودند که با آن‌ها تماس داشته باشند."),
            StoryParagraph("And so, in the abandoned asylum on the edge of the city, a strange new community began to form: a community of the blind, a community of the terrified, a community of those who had been cast out of the world of the seeing and left to fend for themselves.", "و اینگونه، در تیمارستان متروکه حاشیه شهر، جامعه‌ای جدید و عجیب شروع به شکل گرفتن کرد: جامعه‌ای از کورها، جامعه‌ای از هراسندگان، جامعه‌ای از کسانی که از دنیای بینایان رانده شده و رها شده بودند تا خودشان سر کنند."),
            StoryParagraph("Among them was a woman who had not been afflicted — the wife of the ophthalmologist, who had pretended to be blind in order to follow her husband into the quarantine.", "میانشان زنی بود که مبتلا نشده بود — همسر چشم‌پزشک که تظاهر به کوری کرده بود تا به دنبال شوهرش به قرنطینه برود."),
            StoryParagraph("She alone, of all the thousands who would pass through those gates, retained the gift of sight, and she carried this gift as both a blessing and a curse.", "او تنها کسی از میان هزارانی که از آن دروازه‌ها می‌گذشتند بود که موهبت بینایی را حفظ کرد و این موهبت را هم مثل برکت و هم مثل نفرین حمل می‌کرد."),
            StoryParagraph("It was a burden that would weigh upon her more heavily with each passing day, a burden that would grow until it became almost more than any human being could bear.", "باری بود که با هر روزی که می‌گذشت سنگین‌تر بر او فشار می‌آورد، باری که رشد می‌کرد تا وقتی تقریباً بیش از آنچه هر انسانی می‌توانست تحمل کند می‌شد."),
            StoryParagraph("And so the story began, in the white blindness that had overtaken a city, in the quarantine that had become a prison, in the woman who could see and the thousands who could not.", "و اینگونه داستان آغاز شد، در کوری سفیدی که شهری را فرا گرفته بود، در قرنطینه‌ای که به زندان تبدیل شده بود، در زنی که می‌توانست ببیند و هزارانی که نمی‌توانستند."),
            StoryParagraph("It began, as all great stories begin, not with a bang but with a whisper, not with a catastrophe but with a single man, sitting in his car, staring at a whiteness that had replaced the world.", "آغاز شد، همانطور که همه داستان‌های بزرگ آغاز می‌شوند، نه با انفجاری بلکه با زمزمه‌ای، نه با فاجعه‌ای بلکه با یک مرد تنها، که در ماشینش نشسته و به سفیدی‌ای خیره شده بود که جای دنیا را گرفته بود.")
        )
    )

    // ─────────── فصل ۲: همسر دکتر ───────────
    private fun chapter2() = StoryChapter(
        number = 2, title = "The Doctor's Wife", titlePersian = "همسر دکتر",
        paragraphs = listOf(
            StoryParagraph("When the doctor was taken to the quarantine, his wife did not hesitate for even a moment; she declared herself blind, though she could see as clearly as ever, and she followed him into the asylum.", "وقتی دکتر به قرنطینه برده شد، همسرش حتی یک لحظه تردید نکرد؛ خودش را کور اعلام کرد، هرچند مثل همیشه واضح می‌دید و به دنبالش وارد تیمارستان شد."),
            StoryParagraph("She knew the rules: only the blind were permitted inside the quarantine, because only the blind were considered infected, and only the infected were considered a danger to the sighted.", "قوانین را می‌دانست: فقط کورها اجازه ورود به قرنطینه را داشتند، چون فقط کورها آلوده محسوب می‌شدند و فقط آلوده‌ها خطری برای بینایان به شمار می‌آمدند."),
            StoryParagraph("She also knew that by entering the quarantine, she might never be permitted to leave it — that the government, in its desperation, had sealed off the asylum, and that those inside it had effectively been abandoned.", "همچنین می‌دانست که با ورود به قرنطینه ممکن است هرگز اجازه خروج از آن را نیابد — که دولت از سر درماندگی تیمارستان را مهر و موم کرده بود و کسانی که داخل آن بودند عملاً رها شده بودند."),
            StoryParagraph("But she did not care; she loved her husband, and she would not abandon him, and if the price of staying with him was to spend the rest of her life in the company of the blind, then that was a price she was willing to pay.", "اما اهمیتی نمی‌داد؛ شوهرش را دوست داشت و رهایش نمی‌کرد و اگر بهای ماندن با او این بود که بقیه عمرش را در معاشرت با کورها بگذراند، آن بهایی بود که حاضر بود بپردازد."),
            StoryParagraph("She was not a hero, she told herself; she was not a saint; she was simply a woman who loved her husband, and love, she had always believed, was the only thing in this world worth sacrificing for.", "به خودش می‌گفت قهرمان نیست؛ قدیس نیست؛ فقط زنی است که شوهرش را دوست دارد و عشق، همیشه باور داشت، تنها چیزی در این دنیاست که ارزش فداکاری دارد."),
            StoryParagraph("When she arrived at the asylum, she found a scene of pandemonium: hundreds of blind people, most of them newly blinded, stumbling through corridors, colliding with walls, calling out for family members who could not hear them.", "وقتی به تیمارستان رسید، صحنه‌ای از هرج‌ومرج یافت: صدها کور، بیشترشان تازه‌کور، در راهروها تلپ می‌خوردند، به دیوارها برخورد می‌کردند، فریاد اعضای خانواده‌ای می‌زدند که نمی‌شنیدند."),
            StoryParagraph("She made her way through the chaos to the room where her husband had been assigned, and when she found him, sitting on his cot with his face in his hands, she sat down beside him and took his hand in hers.", "از میان آشفتگی به اتاقی که به شوهرش اختصاص داده شده بود راه یافت و وقتی پیدایش کرد، روی تختش نشسته و صورتش در دستانش، کنارش نشست و دستش را در دستانش گرفت."),
            StoryParagraph("He looked up at her with his useless eyes and whispered, 'You should not have come. You should have stayed outside. You should have saved yourself.'", "با چشمان بی‌فایده‌اش به او نگاه کرد و زمزمه کرد: «نباید می‌آمدی. باید بیرون می‌ماندی. باید خودت را نجات می‌دادی.»"),
            StoryParagraph("'Where would I go?' she replied. 'What would I save? My life without you is not a life worth saving.'", "پاسخ داد: «کجا می‌رفتم؟ چه چیزی را نجات می‌دادم؟ زندگی‌ام بدون تو زندگی‌ای نیست که ارزش نجات دادن داشته باشد.»"),
            StoryParagraph("He wept, then, for the first time since the whiteness had descended upon him; and she held him, and she wept too, though her tears were for him and not for herself, because she could see, and she knew that seeing was not the same as being alive.", "و آن وقت گریست، برای اولین بار از وقتی سفیدی بر او نازل شده بود؛ و او در آغوشش گرفت و او هم گریست، هرچند اشک‌هایش برای او بود نه برای خودش، چون می‌توانست ببیند و می‌دانست که دیدن همان زنده بودن نیست."),
            StoryParagraph("In the beginning, the quarantine was merely chaotic — the blind stumbled over one another, argued over beds, formed alliances and rivalries.", "در آغاز، قرنطینه فقط آشوبناک بود — کورها بر یکدیگر می‌افتادند، بر سر تخت‌ها بحث می‌کردند، اتحادها و رقابت‌ها تشکیل می‌دادند."),
            StoryParagraph("But as the days wore on and the food ran short, chaos gave way to something far more sinister.", "اما با گذشت روزها و تمام شدن غذا، آشفتگی جای خود را به چیزی بسیار شوم‌تر داد."),
            StoryParagraph("A man known only as the King of the Ward, a former bartender with a pistol and a talent for intimidation, seized control of the food supply and established a tyranny that would have been unthinkable in the world before the blindness.", "مردی که فقط به‌عنوان پادشاه بخش شناخته می‌شد، ساقی سابق با تپانچه‌ای و استعدادی برای ترساندن، کنترل منابع غذایی را به دست گرفت و استبدادی برپا کرد که در دنیای پیش از کوری غیرقابل تصور می‌بود."),
            StoryParagraph("He demanded that all the food be brought to him, and he distributed it according to his own arbitrary will, rewarding his allies and starving his enemies.", "او خواستار شد تمام غذا به او آورده شود و آن را طبق اراده دلبخواه خودش تقسیم می‌کرد، متحدانش را پاداش می‌داد و دشمنانش را گرسنه نگه می‌داشت."),
            StoryParagraph("When the supply of food proved insufficient to satisfy his greed, he demanded another form of payment: the women of the ward.", "وقتی ذخیره غذا برای ارضای طمعش ناکافی ثابت شد، شکل دیگری از پرداخت را طلب کرد: زنان بخش."),
            StoryParagraph("The women, he decreed, would be made available to him and his followers at specified times, in specified rooms, for specified purposes.", "او حکم کرد که زنان در زمان‌های مشخص، در اتاق‌های مشخص، برای اهداف مشخص در اختیار او و پیروانش قرار گیرند."),
            StoryParagraph("The blind women had no way to resist; they could not see their attackers, could not flee, could not fight back; they could only endure, and hope that the nightmare would end.", "زنان کور راهی برای مقاومت نداشتند؛ نمی‌توانستند مهاجمانشان را ببینند، نمی‌توانستند فرار کنند، نمی‌توانستند مقاومت کنند؛ تنها می‌توانستند تحمل کنند و امیدوار باشند که کابوس پایان یابد."),
            StoryParagraph("The doctor's wife watched all of this in silence, her eyes — the only functioning eyes in the entire asylum — bearing witness to cruelties that no human being should ever have to see.", "همسر دکتر همه این‌ها را در سکوت تماشا می‌کرد، چشمانش — تنها چشمان کارآمد در کل تیمارستان — شاهد ظلم‌هایی بودند که هیچ انسانی هرگز نباید می‌دید."),
            StoryParagraph("She organized the few who retained a shred of decency, formed a quiet resistance, smuggled food from the outside world through a hidden passage, and cared for the sick and the dying as best she could.", "او آن چند نفری که تکه‌ای از اخلاقیات را حفظ کرده بودند سازماندهی کرد، مقاومتی خاموش تشکیل داد، از طریق گذرگاهی پنهان از دنیای بیرون غذا قاچاق می‌کرد و تا جایی که می‌توانست از بیماران و در حال مرگ‌ها مراقبت می‌کرد."),
            StoryParagraph("She could not stop the suffering; she could not prevent the deaths; she could not undo the monstrous transformation that had overtaken her fellow human beings.", "او نمی‌توانست رنج را متوقف کند؛ نمی‌توانست از مرگ‌ها جلوگیری کند؛ نمی‌توانست دگردیسی هیولایی که بر همنوعانش چیره شده بود را جبران کند."),
            StoryParagraph("But she could, at least, refuse to surrender her own humanity; she could, at least, remain the person she had always been.", "اما می‌توانست، حداقل، از تسلیم کردن انسانیت خودش امتناع کند؛ می‌توانست، حداقل، همان شخصی بماند که همیشه بوده بود."),
            StoryParagraph("One night, a fire broke out in one of the wards — whether by accident or by design, no one would ever know.", "یک شب، آتشی در یکی از بخش‌ها شعله‌ور شد — چه تصادفی چه عمدی، هیچ‌کس هرگز نمی‌فهمید."),
            StoryParagraph("The blind residents, unable to see the flames or find the exits, began to scream and stumble in the smoke.", "ساکنان کور، که نمی‌توانستند شعله‌ها را ببینند یا خروجی‌ها را بیابند، شروع کردند به جیغ کشیدن و تلپ خوردن در دود."),
            StoryParagraph("The doctor's wife ran through the burning building, pulling the blind toward the doors, guiding them with her voice, leading them out into the cold night air one by one.", "همسر دکتر از میان ساختمان در حال سوختن دوید، کورها را به سمت درها کشید، با صدایش راهنمایی‌شان کرد و آن‌ها را یکی‌یکی به هوای سرد شب بیرون برد."),
            StoryParagraph("Some of them resisted, because they did not understand what was happening; some of them screamed at her, calling her a demon, an angel, a ghost; but most of them followed her voice, because a voice was the only thing they could still follow.", "برخی‌شان مقاومت کردند، چون نمی‌فهمیدند چه می‌گذرد؛ برخی‌شان بر سرش فریاد زدند و او را دیو، فرشته، شبح نامیدند؛ اما بیشترشان صدایش را دنبال کردند، چون صدا تنها چیزی بود که هنوز می‌توانستند دنبال کنند."),
            StoryParagraph("She saved dozens of lives that night, though no one would ever know her name, and though the world, obsessed with its own suffering, would never pause to thank her.", "او آن شب جان ده‌ها نفر را نجات داد، هرچند هیچ‌کس هرگز نامش را نمی‌دانست و هرچند دنیا که غرق رنج خودش بود هرگز متوقف نمی‌شد تا از او تشکر کند."),
            StoryParagraph("And when the fire had burned itself out, and the survivors stood shivering in the darkness, the doctor's wife looked at the ruin around her and felt, for the first time, the full weight of her loneliness.", "و وقتی آتش خودش را سوزاند و بازماندگان لرزان در تاریکی ایستادند، همسر دکتر به ویرانه‌های اطرافش نگاه کرد و برای اولین بار، وزن کامل تنهایی‌اش را حس کرد."),
            StoryParagraph("She alone could see what had been lost; she alone could remember what the world had been before the whiteness came.", "او تنها کسی بود که می‌توانست ببیند چه از دست رفته بود؛ تنها کسی بود که می‌توانست به یاد بیاورد دنیا پیش از آمدن سفیدی چه بوده."),
            StoryParagraph("She alone carried the burden of knowing, and the knowing was almost more than she could bear.", "تنها کسی بود که بار دانستن را حمل می‌کرد و دانستن تقریباً بیش از آن بود که بتواند تحمل کند."),
            StoryParagraph("The blind were free, in a sense — free from the tyranny of the King of the Ward, free from the confines of the quarantine.", "کورها به نوعی آزاد بودند — آزاد از استبداد پادشاه بخش، آزاد از محدودیت‌های قرنطینه."),
            StoryParagraph("But they were also utterly lost, wandering into a city that had itself gone blind, a world in which nothing was as it had been.", "اما کاملاً گمشده هم بودند، سرگردان به شهری که خودش کور شده بود، دنیایی که در آن هیچ چیز مثل قبل نبود."),
            StoryParagraph("And so they walked together into the ruins, the seeing and the blind, toward a future that none of them could imagine and none of them could refuse.", "و اینگونه با هم به سوی ویرانه‌ها راه افتادند، بینا و کور، به سمت آینده‌ای که هیچ‌کدام نمی‌توانستند تصور کنند و هیچ‌کدام نمی‌توانستند رد کنند.")
        )
    )

    // ─────────── فصل ۳: داخل تیمارستان ───────────
    private fun chapter3() = StoryChapter(
        number = 3, title = "Inside the Asylum", titlePersian = "داخل تیمارستان",
        paragraphs = listOf(
            StoryParagraph("The days inside the asylum blurred into one another, a continuous grey procession of hunger and fear and the slow erosion of everything that had once made the inmates human.", "روزهای داخل تیمارستان در یکدیگر محو می‌شدند، موکبی خاکستری و پیوسته از گرسنگی و ترس و فرسایش آهسته هر چیزی که زمانی زندانیان را انسان می‌ساخت."),
            StoryParagraph("The doctor's wife divided her time with surgical precision: by day she nursed the sick and mediated disputes; by night she slipped through the hidden passage to scavenge for food and supplies in the abandoned streets.", "همسر دکتر وقتش را با دقت جراحی تقسیم می‌کرد: روزها از بیماران مراقبت و در دعواها میانجی‌گری می‌کرد؛ شب‌ها از گذرگاه پنهان می‌خزید تا در خیابان‌های متروکه دنبال غذا و آذوقه بگردد."),
            StoryParagraph("She kept a small notebook in which she recorded everything she observed, not out of any hope that the record would survive, but out of a compulsion to witness, to remember, to bear testimony to the unbearable.", "دفترچه کوچکی نگه می‌داشت که در آن هر چیزی که مشاهده می‌کرد را ثبت می‌کرد، نه از امیدی که این سند باقی بماند، بلکه از اجباری برای شاهد بودن، به یاد آوردن، شهادت دادن به غیرقابل تحمل."),
            StoryParagraph("She noted how the blind developed new senses, new abilities, new ways of navigating their darkness.", "او توجه کرد که کورها چه حواس، چه توانایی‌ها، چه روش‌های جدیدی برای ناوبری در تاریکی‌شان توسعه دادند."),
            StoryParagraph("They learned to read footsteps, to interpret silences, to distinguish between the thousand subtle sounds that a room can make.", "یاد گرفتند صدای قدم‌ها را بخوانند، سکوت‌ها را تفسیر کنند، بین هزار صدای ظریف که یک اتاق می‌تواند بسازد تمایز قائل شوند."),
            StoryParagraph("They learned to identify one another by smell, by the rhythm of breath, by the quality of the air that each person carried with them.", "یاد گرفتند یکدیگر را با بو تشخیص دهند، با ریتم نفس، با کیفیت هوایی که هر شخص با خود حمل می‌کرد."),
            StoryParagraph("They learned to construct mental maps of rooms they could not see, maps that were so detailed and so accurate that they could navigate them with almost the same ease as a sighted person.", "یاد گرفتند نقشه‌های ذهنی از اتاق‌هایی که نمی‌توانستند ببینند بسازند، نقشه‌هایی چنان دقیق و چنان صحیح که می‌توانستند تقریباً با همان سهولت فرد بینا در آن‌ها حرکت کنند."),
            StoryParagraph("She noted how some of them became kinder, more patient, more attuned to the needs of others, while others became crueler, more selfish, more willing to sacrifice their fellow human beings for their own survival.", "او توجه کرد که بعضی‌شان مهربان‌تر، صبورتر، همسوتر با نیازهای دیگران شدند، در حالی که دیگران بی‌رحم‌تر، خودخواه‌تر، آماده‌تر برای قربانی کردن همنوعانشان برای بقای خودشان شدند."),
            StoryParagraph("The blindness, she realized, did not create character; it revealed it; it stripped away the polite veneer of civilization and exposed what had always been underneath.", "دریافت که کوری شخصیت نمی‌سازد؛ آشکارش می‌کند؛ پوسته مؤدبانه تمدن را کنار می‌زند و آنچه همیشه زیرش بود را برهنه می‌کند."),
            StoryParagraph("She began to formulate a theory, not about the disease itself — which remained as mysterious as ever — but about the nature of humanity, about what remains when everything external has been stripped away.", "شروع کرد به فرموله کردن نظریه‌ای، نه درباره خود بیماری — که مثل همیشه مرموز ماند — بلکه درباره ماهیت بشریت، درباره اینکه وقتی همه چیز بیرونی از میان برداشته شده چه باقی می‌ماند."),
            StoryParagraph("Her theory, which she never spoke aloud, was this: that the white blindness was not a disease at all, but a revelation, a stripping away of the illusions that had always blinded human beings to the truth of their own nature.", "نظریه‌اش، که هرگز بلند بر زبان نیاورد، این بود: که کوری سفید اصلاً بیماری نبود، بلکه مکاشفه‌ای بود، کنار زدن توهماتی که همیشه انسان‌ها را نسبت به حقیقت طبیعت خودشان کور کرده بود."),
            StoryParagraph("The world before the blindness, she wrote, had been a world of surfaces, of appearances, of carefully constructed images that concealed the chaos beneath.", "او نوشت که دنیای پیش از کوری دنیایی از سطوح بود، از ظواهر، از تصاویر دقیقاً ساخته‌شده‌ای که آشفتگی زیرشان را پنهان می‌کرد."),
            StoryParagraph("The blindness had torn away the veil and revealed what had always been there.", "کوری پرده را درید و آنچه همیشه آنجا بود را آشکار کرد."),
            StoryParagraph("What had been revealed was not beautiful; it was a landscape of greed and cruelty and indifference, a landscape in which the strong devoured the weak and the fortunate turned away from the suffering of the unfortunate.", "آنچه آشکار شد زیبا نبود؛ منظره‌ای از طمع و ظلم و بی‌تفاوتی بود، منظره‌ای که در آن قوی ضعیف را می‌بلعید و خوش‌شانس از رنج بدشانس روی برمی‌گرداند."),
            StoryParagraph("And yet, even in this landscape, there were moments of grace — a stranger sharing his last piece of bread, a mother sacrificing her own ration for her child, a man giving up his bed for a dying stranger.", "و با این حال، حتی در این منظره، لحظه‌هایی از فیض بود — غریبه‌ای که آخرین تکه نانش را تقسیم می‌کرد، مادری که سهم خودش را برای فرزندش فدا می‌کرد، مردی که تختش را برای غریبه‌ای در حال مرگ رها می‌کرد."),
            StoryParagraph("It was these moments, she concluded, that made the whole terrible ordeal bearable; it was these moments that proved that humanity, for all its flaws, was worth saving.", "او نتیجه گرفت این لحظه‌ها بودند که کل این مصیبت هولناک را تحمل‌پذیر می‌کردند؛ این لحظه‌ها بودند که ثابت می‌کردند بشریت با تمام عیب‌هایش ارزش نجات یافتن داشت."),
            StoryParagraph("One evening, as she was returning from one of her nocturnal expeditions, she encountered a small group of blind children, huddled together in a doorway, abandoned by the adults who had once cared for them.", "یک عصر، وقتی از یکی از سفرهای شبانه‌اش برمی‌گشت، با گروه کوچکی از کودکان کور روبرو شد، در درگاهی جمع شده بودند، رهاشده توسط بزرگسالانی که زمانی از آن‌ها مراقبت می‌کردند."),
            StoryParagraph("She led them back to the asylum, found them food and blankets, and spent the night telling them stories, stories of a world they could not remember and would never see again.", "او آن‌ها را به تیمارستان برد، غذا و پتو برایشان پیدا کرد و شب را با تعریف داستان برایشان گذراند، داستان‌هایی از دنیایی که نمی‌توانستند به یاد آورند و هرگز دوباره نمی‌دیدند."),
            StoryParagraph("The stories were not true, strictly speaking, but they were not lies either; they were myths, fables, parables that carried within them the essential truths that the children would need if they were to survive.", "داستان‌ها دقیقاً راست نبودند، اما دروغ هم نبودند؛ اسطوره بودند، افسانه بودند، تمثیل‌هایی که درونشان حقیقت‌های اساسی‌ای را حمل می‌کردند که بچه‌ها اگر می‌خواستند زنده بمانند به آن‌ها نیاز داشتند."),
            StoryParagraph("And so the doctor's wife, the only seeing person in a world of the blind, became something more than a caretaker; she became a keeper of stories, a guardian of memory, a living link to a past that would otherwise be lost forever.", "و اینگونه همسر دکتر، تنها فرد بینا در دنیایی از کورها، چیزی بیشتر از مراقب شد؛ نگهبان داستان‌ها شد، محافظ خاطره، پیوندی زنده به گذشته‌ای که در غیر این صورت برای همیشه گم می‌شد."),
            StoryParagraph("She did not know if her efforts would matter, if the children would remember her stories, if the world would ever recover from the catastrophe that had befallen it.", "نمی‌دانست تلاش‌هایش مهم خواهند بود یا نه، بچه‌ها داستان‌هایش را به یاد می‌آورند یا نه، دنیا هرگز از فاجعه‌ای که بر آن نازل شده بود بهبود خواهد یافت یا نه."),
            StoryParagraph("But she knew that she had to try, that she had to keep going, that she had to remain human even in a world that had surrendered its humanity.", "اما می‌دانست باید تلاش کند، باید ادامه دهد، باید انسان بماند حتی در دنیایی که انسانیتش را تسلیم کرده بود."),
            StoryParagraph("It was all she had left, and it was, in the end, all that mattered.", "این تمام چیزی بود که برایش مانده بود و در نهایت، تمام چیزی بود که اهمیت داشت."),
            StoryParagraph("Meanwhile, the King of the Ward consolidated his power, expanding his reign of terror from the food supply to every aspect of life within the asylum.", "در همین حال، پادشاه بخش قدرت خود را تحکیم کرد و سلطنت ترور خود را از منابع غذایی به هر جنبه‌ای از زندگی در تیمارستان گسترش داد."),
            StoryParagraph("He appointed lieutenants, divided the inmates into castes, established a hierarchy of privilege and punishment that mirrored, in its cruelty, the hierarchies of the world outside.", "او ستوان‌هایی منصوب کرد، زندانیان را به کاست‌ها تقسیم کرد، سلسله‌مراتبی از امتیاز و مجازات برپا کرد که در بی‌رحمی، سلسله‌مراتب‌های دنیای بیرون را بازتاب می‌داد."),
            StoryParagraph("The doctor's wife, watching this unfold, understood that the blindness had not made people cruel; it had merely removed the constraints that had previously prevented them from acting on their cruelty.", "همسر دکتر، در حالی که این unfold را تماشا می‌کرد، فهمید که کوری مردم را بی‌رحم نکرده بود؛ فقط محدودیت‌هایی که پیش از این مانعشان شده بود بر اساس بی‌رحمی‌شان عمل کنند را برداشته بود."),
            StoryParagraph("And this, she wrote in her notebook, was perhaps the most terrible truth of all: that civilization was not a natural state but a fragile construction, and that it could be dismantled in an instant.", "و این، در دفترش نوشت، شاید هولناک‌ترین حقیقت از همه بود: تمدن نه حالت طبیعی بلکه ساختاری شکننده بود و می‌شد در یک لحظه از هم پاشاند."),
            StoryParagraph("The only thing that could rebuild it, she concluded, was not sight, not intelligence, not power, but love — the willingness to see another person's need and to respond to it, whether or not one could see the person at all.", "تنها چیزی که می‌توانست دوباره بسازدش، نتیجه گرفت، نه بینایی بود، نه هوش، نه قدرت، بلکه عشق — تمایل به دیدن نیاز انسانی دیگر و پاسخ دادن به آن، خواه بتوانی آن شخص را ببینی یا نه.")
        )
    )

    // ─────────── فصل ۴: دنیای جدید ───────────
    private fun chapter4() = StoryChapter(
        number = 4, title = "The New World", titlePersian = "دنیای جدید",
        paragraphs = listOf(
            StoryParagraph("The doctor's wife and her small group eventually found refuge in an empty apartment building on the edge of the city, where they established a community founded on principles that would have seemed utopian in the world before the blindness.", "همسر دکتر و گروه کوچکش در نهایت در ساختمانی خالی در حاشیه شهر پناه گرفتند، جایی که جامعه‌ای بنا کردند بر اصولی که در دنیای پیش از کوری اتوپیایی به نظر می‌رسیدند."),
            StoryParagraph("Everyone contributed according to their abilities; everyone received according to their needs; no one was allowed to hoard, to exploit, or to dominate another.", "همه طبق توانایی‌هایشان مشارکت می‌کردند؛ همه طبق نیازهایشان دریافت می‌کردند؛ هیچ‌کس اجازه نداشت انبار کند، بهره‌کشی کند یا بر دیگری سلطه یابد."),
            StoryParagraph("The blind members learned new skills with astonishing speed: some became gardeners, using their heightened senses of touch and smell to cultivate vegetables in the abandoned courtyards.", "اعضای کور با سرعت شگفت‌انگیزی مهارت‌های جدید یاد گرفتند: بعضی باغبان شدند و از حواس تقویت‌شده لامسه و بویایی‌شان برای کشت سبزیجات در حیاط‌های متروکه استفاده کردند."),
            StoryParagraph("Others became craftsmen, weaving baskets and shaping pottery with hands that had grown almost preternaturally sensitive.", "دیگران صنعتگر شدند، سبد می‌بافتند و سفال با دستانی که تقریباً به‌طرز فراطبیعی حساس شده بودند شکل می‌دادند."),
            StoryParagraph("Still others became musicians, discovering that the loss of sight had sharpened their hearing to such a degree that they could play instruments with a precision and an expressiveness that they had never achieved before.", "باز دیگران موسیقی‌دان شدند و کشف کردند که از دست دادن بینایی شنوایی‌شان را تا چنان درجه‌ای تیز کرده که می‌توانستند سازها را با دقتی و بیان‌گری‌ای بنوازند که هرگز پیش از این نداشته‌اند."),
            StoryParagraph("But outside their small island of civilization, the world continued its descent into savagery.", "اما بیرون از جزیره کوچک تمدنشان، دنیا به سقوطش به توحش ادامه می‌داد."),
            StoryParagraph("The government had collapsed entirely; there was no police, no courts, no hospitals, no schools; the institutions that had held society together had crumbled, and nothing had risen to take their place.", "دولت کاملاً فروپاشیده بود؛ نه پلیسی بود، نه دادگاهی، نه بیمارستانی، نه مدرسه‌ای؛ نهادهایی که جامعه را کنار هم نگه داشته بودند فروریخته بودند و چیزی برای جایگزینی‌شان برنخاسته بود."),
            StoryParagraph("The blind roamed the streets in packs, scavenging for food, fighting over scraps, killing for possessions that no longer held any value.", "کورها در دسته‌ها در خیابان‌ها پرسه می‌زدند، دنبال غذا می‌گشتند، بر سر خرده‌ها می‌جنگیدند، برای دارایی‌هایی که دیگر ارزشی نداشتند می‌کشتند."),
            StoryParagraph("Some had reverted to a state that was barely human, living in sewers, eating whatever they could find — including, in the most extreme cases, the flesh of their fellow human beings.", "بعضی‌ها به حالتی که به‌سختی انسانی بود بازگشته بودند، در فاضلاب‌ها زندگی می‌کردند، هر چه می‌یافتند می‌خوردند — از جمله، در شدیدترین موارد، گوشت همنوعانشان."),
            StoryParagraph("The doctor's wife, on her expeditions to find supplies, witnessed scenes that would haunt her for the rest of her life, scenes that she would never be able to describe, scenes that she could not even fully process in her own mind.", "همسر دکتر در سفرهایش برای یافتن آذوقه شاهد صحنه‌هایی بود که تا آخر عمر تسخیرش می‌کردند، صحنه‌هایی که هرگز نمی‌توانست توصیفشان کند، صحنه‌هایی که حتی نمی‌توانست کاملاً در ذهن خودش پردازش کند."),
            StoryParagraph("She saw a mother carrying the corpse of her child through the streets, refusing to accept that the child was dead.", "مادری را دید که جسد فرزندش را در خیابان‌ها حمل می‌کرد و نمی‌پذیرفت که بچه مرده."),
            StoryParagraph("She saw a group of men fighting over a single can of beans, beating one another bloody until the can was empty and useless.", "گروهی از مردان را دید که بر سر یک قوطی لوبیا می‌جنگیدند و یکدیگر را تا مرز خونین شدن می‌زدند تا وقتی قوطی خالی و بی‌فایده شد."),
            StoryParagraph("She saw a woman lying in the gutter, abandoned by everyone, dying slowly of a disease that no one had the ability or the will to treat.", "زنی را دید که در جوی افتاده بود، توسط همه رهاشده، آهسته از بیماری‌ای می‌مرد که هیچ‌کس توان یا اراده درمانش را نداشت."),
            StoryParagraph("She saw all of this, and she did not turn away, because turning away would have been a betrayal not only of the suffering but of her own humanity.", "همه این‌ها را دید و رو برنگرداند، چون رو برگرداندن نه فقط خیانت به رنج بود، بلکه خیانت به انسانیت خودش."),
            StoryParagraph("She brought back what she could — food, medicine, blankets, sometimes a stray child who had been left behind — and she distributed these gifts among her people, and she asked for nothing in return.", "هر چه می‌توانست برمی‌گرداند — غذا، دارو، پتو، گاهی کودکی سرگردان که جا مانده بود — و این هدایا را بین مردمش تقسیم می‌کرد و در عوض چیزی نمی‌خواست."),
            StoryParagraph("Her community grew, slowly, as the lost and the desperate found their way to her door, drawn by rumors of a place where the blind were treated with dignity, where food was shared, where no one was left to die alone.", "جامعه‌اش آهسته رشد کرد، همان‌طور که گمشدگان و درماندگان راهشان را به درش پیدا می‌کردند، جذب شایعاتی درباره جایی که در آن با کورها با کرامت رفتار می‌شد، جایی که غذا تقسیم می‌شد، جایی که هیچ‌کس تنها رها نمی‌شد تا بمیرد."),
            StoryParagraph("And so, in the midst of the apocalypse, a small utopia took root — fragile, imperfect, threatened from all sides, but alive.", "و اینگونه، در میان آخرالزمان، اتوپیای کوچکی ریشه دواند — شکننده، ناقص، از هر سو تهدیدشده، اما زنده."),
            StoryParagraph("The doctor's wife, watching her community grow, began to hope that the world might, after all, be rebuilt — not as it had been, but as it should have been all along.", "همسر دکتر که رشد جامعه‌اش را تماشا می‌کرد، شروع کرد به امیدواری که دنیا ممکن است، پس از همه این‌ها، بازسازی شود — نه همان‌طور که بوده، بلکه همان‌طور که باید همیشه می‌بود."),
            StoryParagraph("Perhaps, she thought, the blindness had not been a curse but a gift — a terrible gift, but a gift nonetheless — a chance for humanity to start over, to build something better on the ruins of what had come before.", "شاید، فکر کرد، کوری نه نفرین بلکه هدیه‌ای بوده — هدیه‌ای هولناک، اما به هر حال هدیه‌ای — فرصتی برای بشریت تا از نو شروع کند، چیزی بهتر بر ویرانه‌های آنچه پیش از این بود بسازد."),
            StoryParagraph("Perhaps the old world had been too corrupt, too unjust, too blind in its own way to be saved; perhaps only a catastrophe of this magnitude could clear the ground for something new.", "شاید دنیای قدیم برای نجات یافتن بیش از حد فاسد بود، بیش از حد ناعادلانه، به شیوه خودش بیش از حد کور؛ شاید تنها فاجعه‌ای به این بزرگی می‌توانست زمین را برای چیز جدیدی خالی کند."),
            StoryParagraph("She kept this thought in her heart, like a small flame in a vast darkness, and she tended it carefully, because she knew that as long as the flame burned, there was hope.", "این فکر را در قلبش نگه داشت، مثل شراره‌ای کوچک در تاریکی عظیم و با دقت از آن مراقبت کرد، چون می‌دانست تا وقتی شراره می‌سوزد، امید هست."),
            StoryParagraph("And hope, she had learned, was the one thing that no blindness could ever take away.", "و امید، آموخته بود، تنها چیزی است که هیچ کوری هرگز نمی‌تواند بگیرد."),
            StoryParagraph("She wrote these words in her notebook, on a page that would one day be found by a sighted stranger, and she underlined them twice, as though to make certain that they would not be forgotten.", "این کلمات را در دفترش نوشت، در صفحه‌ای که روزی توسط غریبه‌ای بینا پیدا می‌شد و دوبار زیرشان خط کشید، گویی برای اطمینان از اینکه فراموش نمی‌شوند."),
            StoryParagraph("'Hope,' she wrote, 'is not the belief that everything will be fine; it is the determination to make things fine, no matter what.'", "نوشت: «امید باور به اینکه همه چیز خوب می‌شود نیست؛ عزم بر خوب کردن همه چیز است، هر چه پیش آید.»"),
            StoryParagraph("'Hope,' she continued, 'is not a feeling; it is an action. It is the choice to keep going when there is no reason to keep going.'", "ادامه داد: «امید احساس نیست؛ عمل است. انتخابی است برای ادامه دادن وقتی دلیلی برای ادامه دادن نیست.»"),
            StoryParagraph("'And as long as I can make that choice,' she concluded, 'I am not truly blind, even if everyone else in the world has lost their sight.'", "نتیجه گرفت: «و تا وقتی می‌توانم آن انتخاب را بکنم، واقعاً کور نیستم، حتی اگر همه دنیا بینایی‌شان را از دست داده باشند.»")
        )
    )

    // ─────────── فصل ۵: بازگشت بینایی ───────────
    private fun chapter5() = StoryChapter(
        number = 5, title = "The Return of Sight", titlePersian = "بازگشت بینایی",
        paragraphs = listOf(
            StoryParagraph("One morning, without any warning, without any explanation, the first man opened his eyes and saw.", "یک صبح، بدون هیچ هشداری، بدون هیچ توضیحی، مرد اول چشمانش را باز کرد و دید."),
            StoryParagraph("He was lying on a mattress in the community that the doctor's wife had built, and above him he saw a cracked ceiling, and through a window he saw a grey sky, and he wept, because he had forgotten what it was to see anything at all.", "او روی تشکی در جامعه‌ای که همسر دکتر ساخته بود دراز کشیده بود و بالای سرش سقف ترک‌خورده‌ای دید و از پنجره آسمان خاکستری‌ای دید و گریست، چون فراموش کرده بود دیدن هر چیزی چه حسی دارد."),
            StoryParagraph("His cry of joy woke the others, and one by one they opened their eyes, and one by one they discovered that the whiteness had receded, that the world had returned, that they could see again.", "فریاد شادی‌اش دیگران را بیدار کرد و یکی‌یکی چشمانشان را باز کردند و یکی‌یکی کشف کردند که سفیدی عقب‌نشینی کرده، دنیا برگشته، می‌توانند دوباره ببینند."),
            StoryParagraph("The doctor's wife, who had been awake for hours as she always was, watched the miracle unfold around her, and she felt a strange mixture of emotions: relief, certainly, but also something she had not expected — grief.", "همسر دکتر که مثل همیشه ساعت‌ها بیدار بود، معجزه را در اطرافش تماشا کرد و آمیزه عجیبی از احساسات حس کرد: آسودگی، قطعاً، اما چیزی که انتظارش را نداشت هم — غم."),
            StoryParagraph("She grieved for the years that had been lost, for the suffering that could not be undone, for the people who had died, for the person she herself had become, hardened by everything she had witnessed.", "او برای سال‌هایی که از دست رفته بود گریست، برای رنجی که جبران‌ناپذیر بود، برای افرادی که مرده بودند، برای شخصی که خودش شده بود، سخت‌شده توسط هر چیزی که شاهدش بود."),
            StoryParagraph("But when the doctor approached her, his eyes bright with tears and newly-regained vision, and when he took her hands in his and thanked her for everything she had done, she put aside her grief and allowed herself, for the first time in months, to smile.", "اما وقتی دکتر به سمتش آمد، چشمانش از اشک و بینایی تازه‌بازیافته درخشان، و وقتی دست‌هایش را در دستانش گرفت و برای هر کاری که کرده بود تشکر کرد، غمش را کنار گذاشت و برای اولین بار در ماه‌ها، اجازه داد لبخند بزند."),
            StoryParagraph("The world had returned, and with it, the possibility of living, of loving, of being human again.", "دنیا برگشته بود و با آن، امکان زندگی کردن، عشق ورزیدن، دوباره انسان بودن."),
            StoryParagraph("But the world that returned was not the world that had vanished; the cities were in ruins, the institutions were destroyed, the survivors were scarred in ways that would never fully heal.", "اما دنیایی که برگشت همان دنیایی نبود که ناپدید شده بود؛ شهرها در ویرانه بودند، نهادها نابود شده بودند، بازماندگان به شکلی زخم خورده بودند که هرگز کاملاً التیام نمی‌یافت."),
            StoryParagraph("The blind, now seeing, walked through the streets of their ruined city and looked, for the first time, at what they had done to it and to one another during the years of darkness.", "کورها، که حالا می‌دیدند، در خیابان‌های شهر ویرانشان قدم زدند و برای اولین بار، به آنچه در طول سال‌های تاریکی به آن و به یکدیگر کرده بودند نگاه کردند."),
            StoryParagraph("Some wept; some turned away; some refused to accept the evidence of their own eyes.", "بعضی گریستند؛ بعضی رو برگرداندند؛ بعضی از پذیرش شواهد چشمان خودشان امتناع کردند."),
            StoryParagraph("But most, in the end, accepted what they saw and committed themselves to rebuilding.", "اما اکثرشان، در نهایت، آنچه دیدند را پذیرفتند و متعهد به بازسازی شدند."),
            StoryParagraph("It would take decades, they knew; it would take generations; but it could be done, and it would be done, because humanity had survived the worst and was still standing.", "می‌دانستند دهه‌ها طول می‌کشید؛ نسل‌ها طول می‌کشید؛ اما می‌شد انجامش داد و انجام می‌شد، چون بشریت بدترین را جان به‌در برده بود و هنوز ایستاده بود."),
            StoryParagraph("The doctor's wife, watching the reconstruction begin, thought back over everything that had happened — the horror, the suffering, the moments of grace — and she realized that she would not change any of it, even if she could.", "همسر دکتر که آغاز بازسازی را تماشا می‌کرد، به هر چیزی که اتفاق افتاده بود فکر کرد — وحشت، رنج، لحظه‌های فیض — و دریافت که حتی اگر می‌توانست، هیچ‌کدامش را تغییر نمی‌داد."),
            StoryParagraph("Because the blindness had taught her something that sight alone could never have taught her: that humanity is not defined by what it sees, but by what it chooses to do with what it has.", "زیرا کوری چیزی به او آموخته بود که بینایی به‌تنهایی هرگز نمی‌توانست: که بشریت با آنچه می‌بیند تعریف نمی‌شود، بلکه با آنچه انتخاب می‌کند با آنچه دارد انجام دهد."),
            StoryParagraph("She looked at the sun rising over the ruined city, and she allowed herself, for the first time in years, to believe in the future.", "او به خورشیدی نگاه کرد که بر فراز شهر ویران طلوع می‌کرد و برای اولین بار در سال‌ها، اجازه داد به آینده باور کند."),
            StoryParagraph("And so the story of the white blindness ends, not with despair, but with hope.", "و اینگونه داستان کوری سفید به پایان می‌رسد، نه با ناامیدی، بلکه با امید."),
            StoryParagraph("A hope that is fragile, yes, but a hope that is, nevertheless, real.", "امیدی که شکننده است، بله، اما امیدی که با این حال، واقعی است."),
            StoryParagraph("For the world had ended, and the world had been reborn, and the world, in the end, had learned that it could survive even the loss of its own sight.", "زیرا دنیا تمام شده بود و دنیا دوباره متولد شده بود و دنیا، در نهایت، آموخته بود که حتی از دست دادن بینایی خودش را هم می‌تواند جان به‌در ببرد."),
            StoryParagraph("The doctor and his wife, in the years that followed, dedicated themselves to the rebuilding of what had been lost.", "دکتر و همسرش، در سال‌های بعدی، خود را وقف بازسازی آنچه از دست رفته بود کردند."),
            StoryParagraph("They founded a clinic, and then a hospital, and then a school for the blind — not a school that would teach them to accept their blindness, but a school that would teach them to live fully in spite of it.", "کلینیکی تأسیس کردند و بعد بیمارستانی و بعد مدرسه‌ای برای نابینایان — نه مدرسه‌ای که به آن‌ها بپذیراند نابیناییشان را، بلکه مدرسه‌ای که به آن‌ها بیاموزد با وجود آن کامل زندگی کنند."),
            StoryParagraph("They became, in time, symbols of the recovery — not because they had been heroes, but because they had refused to give up.", "در طول زمان، نمادهای بازیابی شدند — نه چون قهرمان بوده بودند، بلکه چون از تسلیم شدن امتناع کرده بودند."),
            StoryParagraph("The doctor's wife published her notebook, under a pseudonym, and it became a kind of sacred text for the survivors — a record of what had happened, yes, but also a guide for how to live when everything you took for granted has been taken away.", "همسر دکتر دفترش را با نام مستعار منتشر کرد و به نوعی متن مقدس برای بازماندگان تبدیل شد — سندی از آنچه اتفاق افتاده بود، بله، اما همچنین راهنمایی برای چطور زندگی کردن وقتی همه چیزهایی که بدیهی می‌دانستی از تو گرفته شده."),
            StoryParagraph("'We survived,' she wrote at the end of the notebook, 'not because we were strong, but because we were together. We survived not because we saw, but because we loved.'", "در پایان دفتر نوشت: «ما جان به‌در بردیم، نه چون قوی بودیم، بلکه چون با هم بودیم. ما جان به‌در بردیم نه چون دیدیم، بلکه چون عشق ورزیدیم.»"),
            StoryParagraph("'And this,' she concluded, 'is the only lesson that matters: that love is stronger than sight, that love is stronger than darkness, that love is stronger than anything the world can throw at us.'", "نتیجه گرفت: «و این تنها درسی است که اهمیت دارد: عشق از بینایی قوی‌تر است، عشق از تاریکی قوی‌تر است، عشق از هر چیزی که دنیا می‌تواند به سمت ما بیندازد قوی‌تر است.»"),
            StoryParagraph("She never spoke of her own role in the survival of her community; she never told anyone that she alone had seen, that she alone had kept the memory of the lost world alive.", "هرگز از نقش خودش در بقای جامعه‌اش صحبت نکرد؛ هرگز به کسی نگفت که تنها او دیده بود، تنها او خاطره دنیای از دست رفته را زنده نگه داشته بود."),
            StoryParagraph("But those who had been with her knew, and they loved her for it, and they would tell the story of the seeing woman in the world of the blind for as long as stories were told.", "اما کسانی که با او بودند می‌دانستند و برایش دوستش داشتند و داستان زن بینا در دنیای کورها را تا وقتی داستان‌ها گفته شوند تعریف می‌کردند."),
            StoryParagraph("And so Saramago's message, hidden beneath the horror of his tale, was this: that humanity's greatest gift is not its ability to see, but its ability to love.", "و اینگونه پیام ساراماگو، پنهان در زیر وحشت داستانش، این بود: که بزرگ‌ترین موهبت بشریت توانایی دیدن نیست، بلکه توانایی عشق ورزیدن است."),
            StoryParagraph("And that even in absolute darkness, love can be a light.", "و اینکه حتی در تاریکی مطلق، عشق می‌تواند نوری باشد."),
            StoryParagraph("The end.", "پایان.")
        )
    )

    // ─────────── فصل ۶: معنا ───────────
    private fun chapter6() = StoryChapter(
        number = 6, title = "The Meaning", titlePersian = "معنا",
        paragraphs = listOf(
            StoryParagraph("Blindness, published in 1995, is one of the most important works of contemporary literature, and one of the most disturbing.", "کوری، منتشرشده در ۱۹۹۵، یکی از مهم‌ترین آثار ادبیات معاصر و یکی از آشفته‌کننده‌ترین است."),
            StoryParagraph("It tells the story of an epidemic of sudden blindness that sweeps through an unnamed city, and of the ways in which the afflicted are quarantined, exploited, and finally abandoned.", "داستان اپیدمی کوری ناگهانی‌ای را تعریف می‌کند که در شهری بی‌نام پخش می‌شود و شیوه‌هایی که مبتلایان قرنطینه، استثمار و سرانجام رها می‌شوند."),
            StoryParagraph("But the novel is not really about blindness; it is about what blindness reveals about human nature.", "اما رمان واقعاً درباره کوری نیست؛ درباره چیزی است که کوری درباره طبیعت انسانی آشکار می‌کند."),
            StoryParagraph("Saramago, like Kafka before him, uses a fantastical premise to explore a realistic truth: that civilization is a fragile thing, that the veneer of civility is thin, that underneath the surface of every human being there are depths of cruelty that we prefer not to acknowledge.", "ساراماگو، همچون کافکای پیش از خودش، از فرضیه‌ای خیالی برای کاوش حقیقتی واقعی استفاده می‌کند: تمدن چیز شکننده‌ای است، پوسته ادب نازک است، زیر سطح هر انسانی عمق‌هایی از بی‌رحمی وجود دارد که ترجیح می‌دهیم به رسمیت نشناسیم."),
            StoryParagraph("The blindness is not a punishment; it is not a curse; it is not a symbol of anything in particular.", "کوری مجازات نیست؛ نفرین نیست؛ نماد چیز خاصی نیست."),
            StoryParagraph("It is simply the instrument that strips away everything external and leaves only what is essential.", "فقط ابزاری است که همه چیز بیرونی را کنار می‌زند و تنها آنچه اساسی است را باقی می‌گذارد."),
            StoryParagraph("What remains, Saramago shows us, is not necessarily evil; it is not necessarily good; it is simply human.", "ساراماگو نشانمان می‌دهد آنچه باقی می‌ماند لزوماً شر نیست؛ لزوماً خیر هم نیست؛ فقط انسانی است."),
            StoryParagraph("The blind develop their own hierarchies, their own cruelties, their own kindnesses; they become, in other words, a mirror of the sighted world they have left behind.", "کورها سلسله‌مراتب خودشان را می‌سازند، بی‌رحمی‌های خودشان، مهربانی‌های خودشان؛ به عبارت دیگر، آینه‌ای از دنیای بینایی می‌شوند که پشت سر گذاشته‌اند."),
            StoryParagraph("The King of the Ward, with his pistol and his lust for power, is not a monster; he is merely a man who has been given absolute authority and has discovered that he likes the taste of it.", "پادشاه بخش با تپانچه‌اش و شهوتش برای قدرت، هیولا نیست؛ فقط مردی است که به او اختیار مطلق داده شده و کشف کرده طعمش را دوست دارد."),
            StoryParagraph("The women who are forced to submit to him are not saints; they are merely people who have been stripped of every power of resistance and are trying to survive.", "زنان مجبور به تسلیم شدن به او قدیس نیستند؛ فقط کسانی هستند که از هر قدرت مقاومتی خلع شده‌اند و تلاش می‌کنند زنده بمانند."),
            StoryParagraph("The doctor's wife, who alone can see, is not a hero; she is merely a woman who has chosen, in the face of unspeakable horror, to remain human.", "همسر دکتر که تنها می‌تواند ببیند، قهرمان نیست؛ فقط زنی است که در برابر وحشت ناگفتنی انتخاب کرده انسان بماند."),
            StoryParagraph("And this, perhaps, is Saramago's deepest message: that heroism is not a matter of extraordinary acts but of ordinary decisions, made moment by moment, day by day.", "و این، شاید، عمیق‌ترین پیام ساراماگو است: قهرمانی مسئله اعمال استثنایی نیست بلکه تصمیم‌های معمولی است، لحظه به لحظه گرفته‌شده، روز به روز."),
            StoryParagraph("The choice to share food, to comfort a stranger, to refuse to participate in cruelty — these are not heroic choices in any dramatic sense, but they are the choices that make us human.", "انتخاب تقسیم غذا، دلداری دادن به غریبه، امتناع از مشارکت در بی‌رحمی — این‌ها در هیچ معنای دراماتیکی انتخاب قهرمانانه نیستند، اما انتخاب‌هایی هستند که ما را انسان می‌کنند."),
            StoryParagraph("The novel is also, and perhaps most pointedly, a political allegory, a satire of the ways in which societies respond to crisis.", "رمان همچنین، و شاید تیزتر، تمثیلی سیاسی است، هجایی از شیوه‌هایی که جوامع به بحران پاسخ می‌دهند."),
            StoryParagraph("The government's response to the epidemic — the quarantine, the isolation, the abandonment — mirrors the responses of governments throughout history to threats that they do not understand.", "پاسخ دولت به اپیدمی — قرنطینه، انزوا، رها کردن — بازتاب پاسخ دولت‌ها در طول تاریخ به تهدیدهایی است که نمی‌فهمند."),
            StoryParagraph("The instinct is always to contain, to isolate, to seal off — to protect the healthy by sacrificing the sick, the whole by sacrificing the part.", "غریره همیشه مهار کردن است، جدا کردن، مهر و موم کردن — محافظت از سالم با قربانی کردن بیمار، از کل با قربانی کردن جزء."),
            StoryParagraph("And the result, always, is that the crisis intensifies, that the sacrifice is futile, that the part that was sacrificed is merely the first of many.", "و نتیجه، همیشه، این است که بحران تشدید می‌شود، قربانی بیهوده است، جزئی که قربانی شد فقط اولین مورد از بسیاری است."),
            StoryParagraph("Saramago wrote the novel at a time when the AIDS epidemic was at its height, and the parallels are unmistakable.", "ساراماگو رمان را زمانی نوشت که اپیدمی ایدز در اوج خودش بود و تشابه‌ها غیرقابل انکارند."),
            StoryParagraph("The panic, the prejudice, the willingness to treat the afflicted as less than human — these were not merely features of the white blindness; they were features of the world Saramago lived in.", "ترس، تعصب، تمایل به رفتار با مبتلایان به‌عنوان کمتر از انسان — این‌ها تنها ویژگی‌های کوری سفید نبودند؛ ویژگی‌های دنیایی بودند که ساراماگو در آن زندگی می‌کرد."),
            StoryParagraph("And the lesson is the same for both: that the only way to respond to crisis is with compassion, that the only way to protect the community is to protect every member of it, that the only way to survive is together.", "و درس برای هر دو یکی است: تنها راه پاسخ به بحران شفقت است، تنها راه محافظت از جامعه محافظت از هر عضوش است، تنها راه بقا با هم است."),
            StoryParagraph("The novel is not a happy book; it is not a comforting book; it is not a book that offers easy answers to difficult questions.", "رمان کتاب شادی نیست؛ کتاب تسلی‌بخش نیست؛ کتابی نیست که پاسخ‌های آسان به پرسش‌های دشوار بدهد."),
            StoryParagraph("But it is a necessary book, a book that forces us to confront the truth about ourselves, the truth that we would prefer not to see.", "اما کتابی ضروری است، کتابی که ما را وادار می‌کند با حقیقت درباره خودمان روبرو شویم، حقیقتی که ترجیح می‌دهیم نبینیم."),
            StoryParagraph("And the truth is this: that we are all capable of cruelty, and that we are all capable of kindness; that we are all capable of becoming the King of the Ward, and that we are all capable of becoming the doctor's wife.", "و حقیقت این است: همه‌مان قادر به بی‌رحمی هستیم و همه‌مان قادر به مهربانی؛ همه‌مان قادر به تبدیل شدن به پادشاه بخش هستیم و همه‌مان قادر به تبدیل شدن به همسر دکتر."),
            StoryParagraph("The choice between them is the choice that defines us, the choice that we make every moment, whether or not we are aware of making it.", "انتخاب میان آن‌ها انتخابی است که ما را تعریف می‌کند، انتخابی که هر لحظه می‌کنیم، خواه از کردنش آگاه باشیم خواه نه."),
            StoryParagraph("Saramago does not tell us which choice to make; he does not preach; he does not moralize.", "ساراماگو به ما نمی‌گوید کدام انتخاب را بکنیم؛ موعظه نمی‌کند؛ اخلاق درس نمی‌دهد."),
            StoryParagraph("He simply shows us the consequences of each choice, and lets us decide for ourselves.", "او تنها پیامدهای هر انتخاب را نشانمان می‌دهد و می‌گذارد خودمان تصمیم بگیریم."),
            StoryParagraph("But the choice he recommends, the choice he celebrates, the choice that gives the novel its hope, is the choice of the doctor's wife: the choice to see what others cannot see, to remember what others have forgotten, to love what others have abandoned.", "اما انتخابش را توصیه می‌کند، انتخابی را که جشن می‌گیرد، انتخابی که به رمان امیدش می‌دهد، انتخاب همسر دکتر است: انتخاب دیدن آنچه دیگران نمی‌بینند، به یاد آوردن آنچه دیگران فراموش کرده‌اند، دوست داشتن آنچه دیگران رها کرده‌اند."),
            StoryParagraph("And that choice, Saramago suggests, is available to all of us — not only in times of catastrophe, but every day of our lives.", "و آن انتخاب، ساراماگو پیشنهاد می‌دهد، برای همه‌مان در دسترس است — نه فقط در زمان‌های فاجعه، بلکه هر روز از زندگی‌مان."),
            StoryParagraph("Because every day there are those who are blind, even though they can see; every day there are those who are invisible, even though they are before our eyes.", "زیرا هر روز کسانی هستند که کورند، هرچند می‌بینند؛ هر روز کسانی هستند که نامرئی‌اند، هرچند پیش چشمان ما هستند."),
            StoryParagraph("The only question is whether we will see them.", "تنها پرسش این است که آیا آن‌ها را می‌بینیم."),
            StoryParagraph("And if we do, then perhaps we can become — each of us, in our own small way — the doctor's wife: a single point of light in a world that has gone dark.", "و اگر ببینیم، شاید بتوانیم بشویم — هر یک از ما، به شیوه کوچک خودمان — همسر دکتر: نقطه نوری واحد در دنیایی که تاریک شده."),
            StoryParagraph("And one light, as the novel shows us, can be enough.", "و یک نور، همانطور که رمان نشانمان می‌دهد، می‌تواند کافی باشد."),
            StoryParagraph("It can save a child, or a stranger, or a community, or perhaps even a world.", "می‌تواند یک بچه را نجات دهد، یا غریبه‌ای، یا جامعه‌ای، یا شاید حتی دنیایی."),
            StoryParagraph("It can be the difference between the white blindness that destroys and the sight that saves.", "می‌تواند تفاوت میان کوری سفیدی باشد که نابود می‌کند و بینایی که نجات می‌دهد."),
            StoryParagraph("The end.", "پایان."),
            StoryParagraph("And the beginning.", "و آغاز."),
            StoryParagraph("For the story of the white blindness is not finished; it is being told, every day, in every city, in every life that is touched by darkness.", "زیرا داستان کوری سفید تمام نشده؛ هر روز گفته می‌شود، در هر شهر، در هر زندگی‌ای که توسط تاریکی لمس شده."),
            StoryParagraph("And it will continue to be told, as long as there are human beings who can see — and who choose to use their sight to help those who cannot.", "و به گفتن ادامه می‌یابد، تا وقتی انسان‌هایی باشند که می‌توانند ببینند — و انتخاب می‌کنند از بینایی‌شان برای کمک به کسانی که نمی‌توانند استفاده کنند.")
        )
    )
}